import React, { useEffect, useMemo, useState } from "react";
import type { AppHandle } from "@app/kit/primitives";
import { motion, useReducedMotion } from "motion/react";
import { Flame, Zap, Home, LayoutGrid, LogOut, Play, GraduationCap, ArrowRight, Check, Trophy, Search, Award, Palette, Terminal, Utensils, Camera, Globe, Wallet, Pencil, Heart, Book, Clock, X } from "lucide-react";

type R = Record<string, any>;
const C = { bg: "#FFF8EC", ink: "#2A1F4D", body: "#463D66", mute: "#5F5680", line: "rgba(42,31,77,.10)", track: "rgba(42,31,77,.09)", sun: "#FFB020", sunDeep: "#E39A12", sunTint: "#FFF0CC", sunText: "#8A5300", ok: "#0A6E55", okTint: "#DDF5EC", coral: "#A8381A" };
const DISPLAY = "'Baloo 2','Nunito',ui-rounded,system-ui,sans-serif";
const BODY = "'Nunito',ui-rounded,system-ui,-apple-system,'Segoe UI',sans-serif";
const SHADOW = "0 1px 2px rgba(42,31,77,.05), 0 8px 24px -12px rgba(42,31,77,.18)";
const EASE: [number, number, number, number] = [0.22, 1, 0.36, 1];
const CSS = "@import url('https://fonts.googleapis.com/css2?family=Baloo+2:wght@600;700;800&family=Nunito:wght@500;600;700;800&display=swap');body{transition-timing-function:cubic-bezier(.22,1,.36,1)!important}.lr ::selection{background:#FFE08A;color:#2A1F4D}.lr :focus-visible{outline:3px solid #2A1F4D;outline-offset:2px}.lr .num{font-variant-numeric:tabular-nums}.lr .noscroll::-webkit-scrollbar{display:none}.lr .noscroll{scrollbar-width:none}.lr input::placeholder{color:#6E6690}";
const CAT: Record<string, { bg: string; fg: string; I: React.ComponentType<{ size?: number; color?: string }> }> = {
  Art: { bg: "#FFE3D9", fg: "#A8381A", I: Palette }, Code: { bg: "#ECE6FF", fg: "#5B3DBF", I: Terminal }, Cooking: { bg: "#FFEDC2", fg: "#8A5300", I: Utensils }, Photo: { bg: "#DCEEFF", fg: "#1F5E9C", I: Camera },
  Languages: { bg: "#D6F3EA", fg: "#0A6E55", I: Globe }, Finance: { bg: "#E4F3D3", fg: "#3F6A12", I: Wallet }, Design: { bg: "#FCE1EF", fg: "#A02D69", I: Pencil }, Lifestyle: { bg: "#DDF2E2", fg: "#22703F", I: Heart },
};
const cat = (k: unknown) => CAT[String(k)] || { bg: C.sunTint, fg: C.sunText, I: Book };

function Cover({ c, className }: { c: R; className?: string }) {
  const [bad, setBad] = useState(false);
  const k = cat(c.category);
  const src = String(c.cover || "");
  if (bad || !src) return <div className={(className || "") + " grid place-items-center"} style={{ background: k.bg }}><k.I size={40} color={k.fg} /></div>;
  return <img src={src} alt="" className={className} onError={() => setBad(true)} />;
}

function Chip({ category }: { category: unknown }) {
  const k = cat(category);
  return <span className="inline-flex items-center gap-1 self-start rounded-full px-2.5 py-1 text-xs font-extrabold" style={{ background: k.bg, color: k.fg }}><k.I size={13} color={k.fg} />{String(category || "Course")}</span>;
}

function Bar({ value, color = C.sun }: { value: number; color?: string }) {
  const reduce = useReducedMotion();
  const v = Math.max(0, Math.min(100, value));
  return (
    <div className="h-2.5 w-full overflow-hidden rounded-full" style={{ background: C.track }} role="progressbar" aria-valuenow={v} aria-valuemin={0} aria-valuemax={100}>
      <motion.div className="h-full rounded-full" style={{ background: color }} initial={{ width: reduce ? v + "%" : 0 }} animate={{ width: v + "%" }} transition={{ duration: reduce ? 0 : 0.8, ease: EASE }} />
    </div>
  );
}

const day = (iso: string, n: number) => { const d = new Date(iso + "T00:00:00Z"); d.setUTCDate(d.getUTCDate() + n); return d.toISOString().slice(0, 10); };
const plural = (n: number, w: string) => n + " " + w + (n === 1 ? "" : "s");

function Shell({ app, active, me, children }: { app: AppHandle; active: "home" | "explore"; me: R; children: React.ReactNode }) {
  const items = [
    { k: "home", label: "My learning", Icon: Home, to: "/home" },
    { k: "explore", label: "Explore", Icon: LayoutGrid, to: "/explore" },
  ];
  const name = String(me.name || app.user.name || "Learner");
  const initials = name.split(" ").map((w) => w[0] || "").slice(0, 2).join("").toUpperCase();
  return (
    <div className="lr min-h-[100dvh] w-full overflow-x-hidden" style={{ background: C.bg, color: C.ink, fontFamily: BODY }}>
      <style>{CSS}</style>
      <aside className="fixed inset-y-0 left-0 hidden w-[248px] flex-col gap-8 border-r bg-white px-5 py-6 lg:flex" style={{ borderColor: C.line }}>
        <div className="flex items-center gap-2.5 px-2">
          <span className="grid h-10 w-10 place-items-center rounded-2xl" style={{ background: C.sun }}><GraduationCap size={22} color={C.ink} /></span>
          <span className="text-2xl font-extrabold tracking-tight" style={{ fontFamily: DISPLAY }}>Learnly</span>
        </div>
        <nav className="flex flex-col gap-1" aria-label="Main">
          {items.map((it) => (
            <button key={it.k} onClick={() => app.navigate(it.to)} aria-current={active === it.k ? "page" : undefined} className="flex h-12 items-center gap-3 rounded-2xl px-4 text-left text-base font-bold transition-colors hover:bg-[#FFF8EC]" style={{ background: active === it.k ? C.sunTint : undefined, color: active === it.k ? C.ink : C.mute }}>
              <it.Icon size={20} color={active === it.k ? C.sunText : C.mute} />{it.label}
            </button>
          ))}
        </nav>
        <div className="mt-auto rounded-2xl p-3" style={{ background: C.bg }}>
          <div className="flex items-center gap-3">
            <span className="grid h-10 w-10 shrink-0 place-items-center rounded-full text-sm font-extrabold" style={{ background: C.ink, color: "#fff" }}>{initials}</span>
            <div className="min-w-0"><p className="truncate text-sm font-extrabold">{name}</p><p className="num text-xs font-bold" style={{ color: C.mute }}>{(Number(me.xp) || 0).toLocaleString("en-GB")} XP</p></div>
          </div>
          <button onClick={() => app.auth.signOut()} className="mt-3 flex h-10 w-full items-center justify-center gap-2 rounded-xl bg-white text-sm font-bold transition-colors hover:bg-[#FFF0CC]" style={{ color: C.body }}><LogOut size={16} />Sign out</button>
        </div>
      </aside>
      <header className="sticky top-0 z-20 flex h-16 items-center gap-2.5 border-b px-4 lg:hidden" style={{ background: "rgba(255,248,236,.96)", borderColor: C.line }}>
        <span className="grid h-9 w-9 place-items-center rounded-xl" style={{ background: C.sun }}><GraduationCap size={20} color={C.ink} /></span>
        <span className="text-xl font-extrabold tracking-tight" style={{ fontFamily: DISPLAY }}>Learnly</span>
        <button onClick={() => app.auth.signOut()} className="ml-auto flex h-11 items-center gap-1.5 rounded-full px-3 text-sm font-bold" style={{ color: C.body }} aria-label="Sign out"><LogOut size={18} />Sign out</button>
      </header>
      <main className="pb-28 lg:pb-16 lg:pl-[248px]">{children}</main>
      <nav className="fixed inset-x-0 bottom-0 z-20 flex border-t bg-white px-2 pb-[max(8px,env(safe-area-inset-bottom))] pt-2 lg:hidden" style={{ borderColor: C.line }} aria-label="Main">
        {items.map((it) => (
          <button key={it.k} onClick={() => app.navigate(it.to)} aria-current={active === it.k ? "page" : undefined} className="flex h-14 flex-1 flex-col items-center justify-center gap-1 rounded-2xl text-xs font-extrabold" style={{ color: active === it.k ? C.ink : C.mute }}>
            <span className="grid h-8 w-14 place-items-center rounded-full" style={{ background: active === it.k ? C.sunTint : "transparent" }}><it.Icon size={20} color={active === it.k ? C.sunText : C.mute} /></span>{it.label}
          </button>
        ))}
      </nav>
    </div>
  );
}

export type StudentHomeProps = { tab?: string; app?: AppHandle };

export default function StudentHome({ tab = "mine", app }: StudentHomeProps) {
  const reduce = useReducedMotion();
  const [filter, setFilter] = useState("All");
  const [q, setQ] = useState("");
  const [today, setToday] = useState("");
  useEffect(() => { setToday(new Date().toISOString().slice(0, 10)); }, []);
  const courses = (app ? app.rows("course") : []) as R[];
  const lessons = (app ? app.rows("lesson") : []) as R[];
  const enrolls = (app ? app.rows("enrollment") : []) as R[];
  const progress = (app ? app.rows("lesson_progress") : []) as R[];
  const students = (app ? app.rows("student") : []) as R[];
  const instructors = (app ? app.rows("instructor") : []) as R[];
  const meId = app ? app.me("student") : undefined;
  const me: R = students.find((s) => s.id === meId) || students[0] || {};
  const loading = app ? (app.loading("course") && courses.length === 0) || (app.loading("enrollment") && enrolls.length === 0 && tab !== "explore") : false;

  const info = useMemo(() => {
    return enrolls.map((e) => {
      const course = courses.find((c) => c.id === e.course_id);
      const ls = lessons.filter((l) => l.course_id === e.course_id).sort((a, b) => Number(a.position) - Number(b.position));
      const doneIds = progress.filter((p) => p.course_id === e.course_id).map((p) => p.lesson_id);
      const total = ls.length || Number(e.total_lessons) || 1;
      const finished = e.status === "completed";
      const done = finished ? total : Math.min(total, doneIds.length);
      const pct = Math.round((done / total) * 100);
      const nextIdx = ls.findIndex((l) => !doneIds.includes(l.id));
      const next = nextIdx >= 0 ? ls[nextIdx] : ls[0];
      return { e, course, done, total, pct, next, nextIdx, finished };
    }).filter((x) => !!x.course);
  }, [enrolls, courses, lessons, progress]);

  if (!app) return null;
  const rank = (x: { finished: boolean; done: number }) => (x.finished ? 2 : x.done > 0 ? 0 : 1);
  const sorted = [...info].sort((a, b) => rank(a) - rank(b) || b.pct - a.pct);
  const hero = sorted.find((x) => !x.finished && x.done > 0) || sorted.find((x) => !x.finished);
  const finishedCount = info.filter((x) => x.finished).length;
  const first = String(me.name || app.user.name || "there").split(" ")[0];
  const streak = Number(me.streak) || 0;
  const last = String(me.last_active || "").slice(0, 10);
  const anchor = today || last;
  const activeToday = !!last && last === anchor;
  const streakDays = new Set<string>();
  if (last && (last === anchor || last === (anchor ? day(anchor, -1) : ""))) for (let i = 0; i < streak; i++) streakDays.add(day(last, -i));
  const liveStreak = streakDays.size;
  const week = anchor ? [6, 5, 4, 3, 2, 1, 0].map((i) => day(anchor, -i)) : [];
  const rise = (i: number) => ({ initial: { opacity: 0, y: reduce ? 0 : 10 }, animate: { opacity: 1, y: 0 }, transition: { duration: reduce ? 0 : 0.4, delay: reduce ? 0 : 0.04 * i, ease: EASE } });
  const lessonCount = (id: unknown) => lessons.filter((l) => l.course_id === id).length;
  const minutes = (id: unknown) => lessons.filter((l) => l.course_id === id).reduce((s, l) => s + (Number(l.minutes) || 0), 0);
  const teacher = (c: R) => { const t = instructors.find((i) => i.id === c.instructor_id); return t ? String(t.name) : ""; };
  const go = (to: string) => () => app.navigate(to);
  const keyGo = (to: string) => (ev: React.KeyboardEvent) => { if (ev.key === "Enter" || ev.key === " ") { ev.preventDefault(); app.navigate(to); } };

  const skeleton = (
    <div className="mt-8 grid grid-cols-1 gap-5 sm:grid-cols-2 xl:grid-cols-3" aria-busy="true" aria-label="Loading courses">
      {[0, 1, 2].map((i) => <div key={i} className="overflow-hidden rounded-3xl bg-white" style={{ boxShadow: SHADOW }}><div className="aspect-[16/9] animate-pulse" style={{ background: C.track }} /><div className="space-y-3 p-5"><div className="h-5 w-2/3 animate-pulse rounded-full" style={{ background: C.track }} /><div className="h-3 w-1/2 animate-pulse rounded-full" style={{ background: C.track }} /></div></div>)}
    </div>
  );

  if (tab === "explore") {
    const enrolledMap = new Map(info.map((x) => [String(x.e.course_id), x]));
    const cats = ["All", ...Array.from(new Set(courses.map((c) => String(c.category)))).sort()];
    const needle = q.trim().toLowerCase();
    const list = courses.filter((c) => (filter === "All" || c.category === filter) && (!needle || (String(c.title) + " " + String(c.summary) + " " + String(c.category) + " " + teacher(c)).toLowerCase().includes(needle)));
    return (
      <Shell app={app} active="explore" me={me}>
        <div className="mx-auto max-w-6xl px-4 pt-6 lg:px-10 lg:pt-12">
          <motion.h1 {...rise(0)} className="text-4xl font-extrabold leading-tight tracking-tight lg:text-5xl" style={{ fontFamily: DISPLAY }}>Explore courses</motion.h1>
          <motion.p {...rise(1)} className="mt-1 max-w-xl text-lg font-semibold" style={{ color: C.mute }}>{courses.length ? plural(courses.length, "bite-sized course") + ", each a handful of five-minute lessons with a quick quiz." : "Short, friendly courses with a quick quiz after every lesson."}</motion.p>
          <div className="mt-6 flex flex-col gap-3">
            <label className="relative block w-full max-w-md">
              <span className="sr-only">Search courses</span>
              <Search size={18} color={C.mute} className="pointer-events-none absolute left-4 top-1/2 -translate-y-1/2" />
              <input type="search" value={q} onChange={(e) => setQ(e.target.value)} placeholder="Search courses or teachers" className="h-12 w-full rounded-full border-2 bg-white pl-11 pr-4 text-base font-semibold outline-none focus:border-[#E39A12]" style={{ borderColor: C.line }} />
            </label>
            <div className="noscroll -mx-4 flex gap-2 overflow-x-auto px-4 pb-1 lg:mx-0 lg:flex-wrap lg:overflow-visible lg:px-0" role="tablist" aria-label="Categories">
              {cats.map((k) => (
                <button key={k} role="tab" aria-selected={filter === k} onClick={() => setFilter(k)} className="h-11 shrink-0 rounded-full border-2 px-4 text-sm font-extrabold transition-colors" style={{ background: filter === k ? C.ink : "#fff", borderColor: filter === k ? C.ink : C.line, color: filter === k ? "#fff" : C.body }}>{k}</button>
              ))}
            </div>
          </div>
          {loading ? skeleton : list.length === 0 ? (
            <div className="mt-8 rounded-3xl bg-white px-6 py-12 text-center" style={{ boxShadow: SHADOW }}>
              <span className="mx-auto grid h-14 w-14 place-items-center rounded-2xl" style={{ background: C.sunTint }}><Search size={26} color={C.sunText} /></span>
              <p className="mt-4 text-2xl font-extrabold" style={{ fontFamily: DISPLAY }}>{courses.length ? "No courses match that" : "No courses yet"}</p>
              <p className="mx-auto mt-1 max-w-sm font-semibold" style={{ color: C.mute }}>{courses.length ? "Try a different word or pick another category." : "Teachers are putting the first courses together. Check back soon."}</p>
              {courses.length > 0 && <button onClick={() => { setQ(""); setFilter("All"); }} className="mt-5 inline-flex h-11 items-center gap-2 rounded-full border-2 px-5 text-sm font-extrabold" style={{ borderColor: C.line }}><X size={16} />Clear filters</button>}
            </div>
          ) : (
            <div className="mt-6 grid grid-cols-1 gap-5 sm:grid-cols-2 xl:grid-cols-3">
              {list.map((c, i) => {
                const mine = enrolledMap.get(String(c.id));
                const to = "/courses/" + c.id;
                return (
                  <motion.article key={c.id} {...rise(i + 2)} role="link" tabIndex={0} onClick={go(to)} onKeyDown={keyGo(to)} aria-label={String(c.title)} className="group flex cursor-pointer flex-col overflow-hidden rounded-3xl bg-white transition-shadow hover:shadow-lg" style={{ boxShadow: SHADOW }}>
                    <div className="relative aspect-[16/9] overflow-hidden"><Cover c={c} className="h-full w-full object-cover transition-transform duration-500 group-hover:scale-[1.03]" /></div>
                    <div className="flex flex-1 flex-col p-5">
                      <div className="flex items-center justify-between gap-2"><Chip category={c.category} />{mine && <span className="rounded-full px-2.5 py-1 text-xs font-extrabold" style={{ background: mine.finished ? C.okTint : C.sunTint, color: mine.finished ? C.ok : C.sunText }}>{mine.finished ? "Finished" : "Enrolled · " + mine.pct + "%"}</span>}</div>
                      <h3 className="mt-3 text-xl font-extrabold leading-snug" style={{ fontFamily: DISPLAY }}>{String(c.title)}</h3>
                      {teacher(c) && <p className="text-sm font-bold" style={{ color: C.mute }}>with {teacher(c)}</p>}
                      <p className="mt-2 line-clamp-2 text-base font-medium leading-relaxed" style={{ color: C.body }}>{String(c.summary || "")}</p>
                      <p className="num mt-auto flex flex-wrap items-center gap-x-3 gap-y-1 pt-4 text-sm font-bold" style={{ color: C.mute }}>
                        <span className="capitalize">{String(c.level)}</span><span aria-hidden="true">·</span><span>{plural(lessonCount(c.id), "lesson")}</span><span aria-hidden="true">·</span><span>{minutes(c.id)} min</span>
                      </p>
                    </div>
                  </motion.article>
                );
              })}
            </div>
          )}
        </div>
      </Shell>
    );
  }

  return (
    <Shell app={app} active="home" me={me}>
      <div className="mx-auto max-w-6xl px-4 pt-6 lg:px-10 lg:pt-12">
        <motion.h1 {...rise(0)} className="text-4xl font-extrabold leading-tight tracking-tight lg:text-5xl" style={{ fontFamily: DISPLAY }}>Hi {first}</motion.h1>
        <motion.p {...rise(1)} className="mt-1 text-lg font-semibold" style={{ color: C.mute }}>
          {liveStreak === 0 ? "Finish one lesson today to start a streak." : activeToday ? "You learned today. Your streak is safe until tomorrow." : "One lesson today keeps your " + liveStreak + "-day streak alive."}
        </motion.p>

        <motion.section {...rise(2)} aria-label="Your progress" className="mt-6 grid grid-cols-2 gap-px overflow-hidden rounded-3xl lg:grid-cols-[1.6fr_1fr_1fr]" style={{ background: C.line, boxShadow: SHADOW }}>
          <div className="col-span-2 flex flex-col gap-3 bg-white p-5 lg:col-span-1">
            <div className="flex items-center gap-2"><Flame size={20} color={C.coral} fill={liveStreak ? "#FF9A6B" : "none"} /><span className="num text-lg font-extrabold">{plural(liveStreak, "day")}</span><span className="text-sm font-bold" style={{ color: C.mute }}>streak</span></div>
            {week.length > 0 && (
              <ol className="grid grid-cols-7 gap-1.5" aria-label="Last 7 days">
                {week.map((d) => {
                  const on = streakDays.has(d);
                  const isToday = d === anchor;
                  const label = new Date(d + "T00:00:00Z").toLocaleDateString("en-GB", { weekday: "short", timeZone: "UTC" });
                  return (
                    <li key={d} className="flex flex-col items-center gap-1" aria-label={label + (on ? ", learned" : "")}>
                      <span className="grid h-9 w-9 place-items-center rounded-full text-xs font-extrabold" style={{ background: on ? C.sun : "transparent", border: on ? "none" : "2px " + (isToday ? "solid " + C.ink : "dashed rgba(42,31,77,.22)"), color: C.ink }}>{on ? <Check size={16} strokeWidth={3} /> : null}</span>
                      <span className="text-xs font-bold" style={{ color: isToday ? C.ink : C.mute }}>{isToday ? "Today" : label.slice(0, 2)}</span>
                    </li>
                  );
                })}
              </ol>
            )}
          </div>
          <div className="bg-white p-5"><Zap size={20} color={C.sunText} /><p className="num mt-2 text-3xl font-extrabold leading-none" style={{ fontFamily: DISPLAY }}>{(Number(me.xp) || 0).toLocaleString("en-GB")}</p><p className="mt-1 text-sm font-bold" style={{ color: C.mute }}>XP earned</p></div>
          <div className="bg-white p-5"><Trophy size={20} color={C.ok} /><p className="num mt-2 text-3xl font-extrabold leading-none" style={{ fontFamily: DISPLAY }}>{finishedCount}</p><p className="mt-1 text-sm font-bold" style={{ color: C.mute }}>{finishedCount === 1 ? "course finished" : "courses finished"}</p></div>
        </motion.section>

        {loading ? skeleton : (
          <>
            {hero && hero.course && hero.next && (
              <motion.section {...rise(3)} aria-label="Continue learning" className="mt-6 grid overflow-hidden rounded-3xl md:grid-cols-[1fr_300px]" style={{ background: C.sun }}>
                <div className="p-6 lg:p-8">
                  <p className="text-sm font-extrabold" style={{ color: "#5C3A00" }}>{hero.done > 0 ? "Pick up where you left off" : "Ready when you are"}</p>
                  <h2 className="mt-1 text-3xl font-extrabold leading-tight tracking-tight lg:text-4xl" style={{ fontFamily: DISPLAY }}>{String(hero.course.title)}</h2>
                  <p className="num mt-2 text-base font-bold" style={{ color: "#4A3200" }}>Lesson {hero.nextIdx + 1} of {hero.total} · {String(hero.next.title)} · {Number(hero.next.minutes) || 5} min</p>
                  <div className="mt-4 flex items-center gap-3"><div className="flex-1"><Bar value={hero.pct} color={C.ink} /></div><span className="num text-sm font-extrabold">{hero.pct}%</span></div>
                  <button onClick={go("/lessons/" + hero.next.id)} className="mt-6 inline-flex h-12 items-center gap-2 rounded-full px-6 text-base font-extrabold text-white transition-transform active:translate-y-px" style={{ background: C.ink }}><Play size={16} fill="#fff" />{hero.done > 0 ? "Continue lesson" : "Start lesson 1"}</button>
                </div>
                <div className="relative hidden md:block"><Cover c={hero.course} className="absolute inset-0 h-full w-full object-cover" /></div>
              </motion.section>
            )}

            <div className="mt-10 flex items-end justify-between gap-4">
              <h2 className="text-2xl font-extrabold tracking-tight" style={{ fontFamily: DISPLAY }}>My courses</h2>
              <button onClick={go("/explore")} className="flex h-11 items-center gap-1 rounded-full px-2 text-sm font-extrabold" style={{ color: C.sunText }}>Browse all<ArrowRight size={16} /></button>
            </div>
            {sorted.length === 0 ? (
              <div className="mt-4 rounded-3xl bg-white px-6 py-12 text-center" style={{ boxShadow: SHADOW }}>
                <span className="mx-auto grid h-14 w-14 place-items-center rounded-2xl" style={{ background: C.sunTint }}><Book size={26} color={C.sunText} /></span>
                <p className="mt-4 text-2xl font-extrabold" style={{ fontFamily: DISPLAY }}>Pick your first course</p>
                <p className="mx-auto mt-1 max-w-sm font-semibold" style={{ color: C.mute }}>Every course is a few five-minute lessons. Start one today and your streak begins.</p>
                <button onClick={go("/explore")} className="mt-6 inline-flex h-12 items-center gap-2 rounded-full px-6 text-base font-extrabold transition-transform active:translate-y-[3px]" style={{ background: C.sun, boxShadow: "0 4px 0 " + C.sunDeep }}>Explore courses<ArrowRight size={18} /></button>
              </div>
            ) : (
              <div className="mt-4 grid grid-cols-1 gap-5 sm:grid-cols-2 xl:grid-cols-3">
                {sorted.map((x, i) => {
                  const c = x.course as R;
                  const to = "/courses/" + c.id;
                  return (
                    <motion.article key={String(x.e.id)} {...rise(i + 4)} role="link" tabIndex={0} onClick={go(to)} onKeyDown={keyGo(to)} aria-label={String(c.title)} className="group flex cursor-pointer flex-col overflow-hidden rounded-3xl bg-white transition-shadow hover:shadow-lg" style={{ boxShadow: SHADOW }}>
                      <div className="relative aspect-[16/9] overflow-hidden">
                        <Cover c={c} className="h-full w-full object-cover transition-transform duration-500 group-hover:scale-[1.03]" />
                        {x.finished && <span className="absolute right-3 top-3 inline-flex items-center gap-1 rounded-full bg-white px-2.5 py-1 text-xs font-extrabold" style={{ color: C.ok }}><Trophy size={13} />Finished</span>}
                      </div>
                      <div className="flex flex-1 flex-col p-5">
                        <Chip category={c.category} />
                        <h3 className="mt-3 text-xl font-extrabold leading-snug" style={{ fontFamily: DISPLAY }}>{String(c.title)}</h3>
                        <p className="mt-0.5 text-sm font-bold" style={{ color: C.mute }}>{teacher(c) ? "with " + teacher(c) : plural(x.total, "lesson")}</p>
                        <div className="mt-auto pt-5">
                          {x.finished ? (
                            <button onClick={(ev) => { ev.stopPropagation(); app.navigate("/certificate/" + c.id); }} className="inline-flex h-11 items-center gap-2 rounded-full px-4 text-sm font-extrabold" style={{ background: C.okTint, color: C.ok }}><Award size={16} />View certificate</button>
                          ) : (
                            <>
                              <div className="num mb-2 flex items-center justify-between text-sm font-bold" style={{ color: C.mute }}><span>{x.done === 0 ? "Not started" : x.done + " of " + x.total + " lessons"}</span><span className="flex items-center gap-1"><Clock size={14} />{minutes(c.id)} min</span></div>
                              <Bar value={x.pct} />
                            </>
                          )}
                        </div>
                      </div>
                    </motion.article>
                  );
                })}
              </div>
            )}
          </>
        )}
      </div>
    </Shell>
  );
}

