type R = Record<string, any>;
const C = { bg: "#FFF8EC", ink: "#2A1F4D", body: "#463D66", mute: "#5F5680", line: "rgba(42,31,77,.10)", track: "rgba(42,31,77,.09)", sun: "#FFB020", sunDeep: "#E39A12", sunTint: "#FFF0CC", sunText: "#8A5300", ok: "#0A6E55", okTint: "#DDF5EC", bad: "#A8381A", badTint: "#FFE8E0" };
const DISPLAY = "'Baloo 2','Nunito',ui-rounded,system-ui,sans-serif";
