const CAT: Record<string, { bg: string; fg: string; I: React.ComponentType<{ size?: number; color?: string }> }> = {
  Art: { bg: "#FFE3D9", fg: "#A8381A", I: Palette }, Code: { bg: "#ECE6FF", fg: "#5B3DBF", I: Terminal }, Cooking: { bg: "#FFEDC2", fg: "#8A5300", I: Utensils }, Photo: { bg: "#DCEEFF", fg: "#1F5E9C", I: Camera },
  Languages: { bg: "#D6F3EA", fg: "#0A6E55", I: Globe }, Finance: { bg: "#E4F3D3", fg: "#3F6A12", I: Wallet }, Design: { bg: "#FCE1EF", fg: "#A02D69", I: Pencil }, Lifestyle: { bg: "#DDF2E2", fg: "#22703F", I: Heart },
};
const cat = (k: unknown) => CAT[String(k)] || { bg: C.sunTint, fg: C.sunText, I: Book };

function Img({ src, fallback, category, className }: { src: unknown; fallback?: unknown; category: unknown; className?: string }) {
  const [stage, setStage] = useState(0);
  const k = cat(category);
  const list = [String(src || ""), String(fallback || "")].filter((s) => s.length > 0);
  if (stage >= list.length) return <div className={(className || "") + " grid place-items-center"} style={{ background: k.bg }}><k.I size={32} color={k.fg} /></div>;
  return <img src={list[stage]} alt="" className={className} onError={() => setStage((s) => s + 1)} />;
}

function Av({ name, cls }: { name: string; cls: string }) {
  return <span className={cls + " grid shrink-0 place-items-center rounded-full font-extrabold"} style={{ background: C.ink, color: "#fff" }}>{name.split(" ").map((w) => w[0] || "").slice(0, 2).join("").toUpperCase()}</span>;
