                          )}
                        </div>
                        {isNext ? <span className="hidden shrink-0 rounded-full px-3 py-1.5 text-xs font-extrabold sm:inline" style={{ background: C.sunTint, color: C.sunText }}>Up next</span> : null}
                        <ChevronRight size={20} color={C.mute} className="shrink-0" />
                      </button>
                    </motion.li>
                  );
                })}
              </ol>
            )}
          </div>
          <div className="hidden lg:block"><div className="sticky top-24">{actionCard}</div></div>
        </div>
      </div>
    </>
  );
}

