function Confetti({ count }: { count: number }) {
  const reduce = useReducedMotion();
  if (reduce) return null;
  return (
    <div className="pointer-events-none fixed inset-0 z-50 overflow-hidden" aria-hidden="true">
      {Array.from({ length: count }).map((_, i) => {
        const a = (i / count) * Math.PI * 2 + (i % 5) * 0.3;
        const d = 120 + ((i * 53) % 200);
        const w = 7 + (i % 3) * 3;
        return (
          <motion.span key={i} className="absolute left-1/2 top-[40%]" style={{ width: w, height: i % 3 === 0 ? w : w * 1.7, background: CONF[i % CONF.length], borderRadius: i % 3 === 0 ? 999 : 2 }}
            initial={{ x: 0, y: 0, opacity: 1, rotate: 0 }} animate={{ x: Math.cos(a) * d, y: Math.sin(a) * d * 0.6 + 240, opacity: [1, 1, 0], rotate: 200 + i * 30 }} transition={{ duration: 1.6 + (i % 5) * 0.12, ease: EASE }} />
        );
      })}
    </div>
  );
}

