export default function LearnlyLogin(props: LearnlyLoginProps) {
  const app = props.app;
  const reduce = useReducedMotion();
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [name, setName] = useState("");
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState<string | null>(null);
  const auth = app ? app.auth : null;
  const signup = !!auth && auth.mode === "signup";
  const providers = auth && Array.isArray(auth.providers) ? auth.providers : [];
  const canSignUp = !!auth && !!auth.canSignUp;

  const submit = async () => {
    if (!auth || busy) return;
    if (!email.trim() || !password) { setErr("Enter your email and password to continue."); return; }
    setBusy(true); setErr(null);
    try {
      if (signup) await auth.signUp({ email, password, name });
      else await auth.signIn(email, password);
    } catch (e) { setErr(e instanceof Error && e.message ? e.message : "That email and password don't match. Check them and try again."); }
    setBusy(false);
  };

  const social = async (p: string) => {
    if (!auth) return;
    setErr(null);
    try { await auth.startProvider(p); } catch (e) { setErr(e instanceof Error && e.message ? e.message : "We couldn't open that sign-in. Try again in a moment."); }
  };

  const field = "h-12 w-full rounded-2xl border-2 bg-white px-4 text-base font-semibold outline-none transition-colors focus:border-[#E39A12]";
  const label = "mb-1.5 block text-sm font-bold";
  const enter = (d: number) => ({ initial: { opacity: 0, y: reduce ? 0 : 14 }, animate: { opacity: 1, y: 0 }, transition: { duration: reduce ? 0 : 0.5, delay: reduce ? 0 : d, ease: EASE } });
  const perks = [
    { I: Clock, t: "Five-minute lessons that fit a coffee break" },
    { I: Lightbulb, t: "Quick quizzes with an AI tutor for hints" },
    { I: Award, t: "A certificate for every course you finish" },
  ];

  return (
    <div className="lr relative min-h-[100dvh] w-full overflow-x-hidden" style={{ background: C.bg, color: C.ink, fontFamily: BODY }}>
      <style>{CSS}</style>
      <div className="mx-auto grid min-h-[100dvh] max-w-6xl md:grid-cols-[1.05fr_1fr] md:items-center md:gap-10 md:px-8 lg:gap-16">
        <div className="relative px-5 pt-5 md:px-0 md:pt-0">
          <div className="flex items-center gap-2.5">
            <span className="grid h-10 w-10 place-items-center rounded-2xl" style={{ background: C.sun }}><GraduationCap size={22} color={C.ink} /></span>
            <span className="text-2xl font-extrabold tracking-tight" style={{ fontFamily: DISPLAY }}>Learnly</span>
          </div>
          <div className="relative mx-auto mt-2 h-[30vh] max-h-[260px] min-h-[180px] w-full max-w-[420px] md:mt-8 md:h-[300px] md:max-h-none md:max-w-[460px]" aria-hidden="true">
            {TILES.map((t) => (
              <span key={t.ch} className="absolute grid h-11 w-11 place-items-center rounded-2xl bg-white text-2xl font-extrabold" style={{ left: t.x, top: t.y, color: t.c, transform: "rotate(" + t.r + "deg)", boxShadow: "0 2px 6px rgba(42,31,77,.10)", fontFamily: DISPLAY }}>{t.ch}</span>
            ))}
            <motion.div className="absolute inset-0" {...enter(0.05)}>
              <Books className="mx-auto h-full w-auto" />
            </motion.div>
          </div>
          <div className="hidden md:block">
            <motion.h2 {...enter(0.1)} className="mt-8 text-5xl font-extrabold leading-[1.05] tracking-tight" style={{ fontFamily: DISPLAY }}>Learn a little,<br />every day.</motion.h2>
            <ul className="mt-6 flex flex-col gap-3">
              {perks.map((p, i) => (
                <motion.li key={p.t} {...enter(0.16 + i * 0.05)} className="flex items-center gap-3 text-lg font-semibold" style={{ color: C.body }}>
                  <span className="grid h-9 w-9 shrink-0 place-items-center rounded-xl" style={{ background: "#FFF0CC" }}><p.I size={18} color="#8A5300" /></span>{p.t}
                </motion.li>
              ))}
            </ul>
          </div>
        </div>

        <motion.div
          initial={{ opacity: 0, y: reduce ? 0 : 24 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: reduce ? 0 : 0.55, ease: EASE, delay: reduce ? 0 : 0.1 }}
          className="relative w-full rounded-t-[32px] bg-white px-5 pb-8 pt-6 md:rounded-[32px] md:px-9 md:py-9"
          style={{ boxShadow: "0 -8px 32px -12px rgba(42,31,77,.18), 0 18px 48px -20px rgba(42,31,77,.22)" }}
        >
          <h1 className="text-3xl font-extrabold leading-tight tracking-tight" style={{ fontFamily: DISPLAY }}>{signup ? "Start your streak" : "Welcome back"}</h1>
          <p className="mt-1 text-base font-semibold" style={{ color: C.mute }}>{signup ? "Create a free account and take your first lesson today." : "Sign in to pick up your next lesson."}</p>

          {canSignUp && (
            <div className="relative mt-5 flex rounded-full p-1" style={{ background: "#F1EEF6" }} role="tablist" aria-label="Account">
              {[{ k: false, t: "I'm back" }, { k: true, t: "I'm new" }].map((tab) => (
                <button key={tab.t} type="button" role="tab" aria-selected={signup === tab.k} onClick={() => { setErr(null); if (auth) auth.setMode(tab.k ? "signup" : "login"); }} className="relative h-11 flex-1 rounded-full text-base font-bold" style={{ color: signup === tab.k ? C.ink : "#4F4670" }}>
                  {signup === tab.k && <motion.span layoutId="auth-pill" className="absolute inset-0 rounded-full bg-white" style={{ boxShadow: "0 1px 4px rgba(42,31,77,.14)" }} transition={{ duration: reduce ? 0 : 0.3, ease: EASE }} />}
                  <span className="relative">{tab.t}</span>
                </button>
              ))}
            </div>
          )}

          <form onSubmit={(e) => { e.preventDefault(); submit(); }} className="mt-5" noValidate>
            <div className="flex flex-col gap-4">
              <AnimatePresence initial={false}>
                {signup && (
                  <motion.div key="name" initial={{ opacity: 0, height: 0 }} animate={{ opacity: 1, height: "auto" }} exit={{ opacity: 0, height: 0 }} transition={{ duration: reduce ? 0 : 0.25, ease: EASE }} className="overflow-hidden">
                    <label htmlFor="lr-name" className={label}>Your name</label>
                    <input id="lr-name" type="text" placeholder="e.g. Priya Nair" autoComplete="name" value={name} onChange={(e) => setName(e.target.value)} className={field} style={{ borderColor: C.line }} />
                  </motion.div>
                )}
              </AnimatePresence>
              <div>
                <label htmlFor="lr-email" className={label}>Email</label>
                <input id="lr-email" aria-label="Email" type="email" placeholder="you@example.com" autoComplete="email" value={email} onChange={(e) => setEmail(e.target.value)} className={field} style={{ borderColor: C.line }} />
              </div>
              <div>
                <label htmlFor="lr-pass" className={label}>Password</label>
                <input id="lr-pass" aria-label="Password" type="password" placeholder={signup ? "At least 8 characters" : "Your password"} autoComplete={signup ? "new-password" : "current-password"} value={password} onChange={(e) => setPassword(e.target.value)} className={field} style={{ borderColor: C.line }} />
              </div>
            </div>
            <AnimatePresence>{err && (
              <motion.p role="alert" initial={{ opacity: 0, y: -4 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0 }} transition={{ duration: 0.2, ease: EASE }} className="mt-4 flex items-start gap-2 rounded-2xl p-3 text-sm font-bold" style={{ background: C.badTint, color: C.bad }}>
                <AlertCircle size={18} className="mt-px shrink-0" />{err}
              </motion.p>
            )}</AnimatePresence>
            <button type="submit" disabled={busy} className="mt-5 h-14 w-full rounded-full text-lg font-extrabold transition-transform active:translate-y-[3px] disabled:opacity-70" style={{ background: C.sun, color: C.ink, boxShadow: "0 4px 0 " + C.sunDeep, fontFamily: DISPLAY }}>{busy ? "One moment…" : signup ? "Create my account" : "Sign in"}</button>
          </form>

          {providers.length > 0 && (
            <>
              <div className="my-5 flex items-center gap-3 text-sm font-bold" style={{ color: C.mute }}>
                <span className="h-px flex-1" style={{ background: C.line }} />or<span className="h-px flex-1" style={{ background: C.line }} />
              </div>
              <div className="flex flex-col gap-3">
                {providers.map((p) => (
                  <button key={p.name} type="button" onClick={() => social(p.name)} className="flex h-12 w-full items-center justify-center gap-3 rounded-full border-2 bg-white text-base font-bold transition-colors hover:bg-[#FFF8EC]" style={{ borderColor: C.line, color: C.ink }}>
                    {p.name === "google" ? <GoogleG /> : null}Continue with {p.label}
                  </button>
                ))}
              </div>
            </>
          )}
          <p className="mt-5 text-center text-sm font-semibold" style={{ color: C.mute }}>Free to start. No card, no catch.</p>
        </motion.div>
      </div>
    </div>
  );
}

import React, { useEffect, useState } from "react";
