import { GraduationCap, LogOut, Plus, Users, Book, X, Check, ChevronRight, Info, AlertCircle, Activity, Trophy, Shield, Palette, Terminal, Utensils, Camera, Globe, Wallet, Pencil, Heart } from "lucide-react";

type R = Record<string, any>;
const C = { bg: "#FFF8EC", ink: "#2A1F4D", body: "#463D66", mute: "#5F5680", line: "rgba(42,31,77,.10)", track: "rgba(42,31,77,.09)", sun: "#FFB020", sunDeep: "#E39A12", sunTint: "#FFF0CC", sunText: "#8A5300", ok: "#0A6E55", okTint: "#DDF5EC", bad: "#A8381A", badTint: "#FFE8E0" };
const DISPLAY = "'Baloo 2','Nunito',ui-rounded,system-ui,sans-serif";
const BODY = "'Nunito',ui-rounded,system-ui,-apple-system,'Segoe UI',sans-serif";
const SHADOW = "0 1px 2px rgba(42,31,77,.05), 0 8px 24px -12px rgba(42,31,77,.18)";
const EASE: [number, number, number, number] = [0.22, 1, 0.36, 1];
const CSS = "@import url('https://fonts.googleapis.com/css2?family=Baloo+2:wght@600;700;800&family=Nunito:wght@500;600;700;800&display=swap');body{transition-timing-function:cubic-bezier(.22,1,.36,1)!important}.lr ::selection{background:#FFE08A;color:#2A1F4D}.lr :focus-visible{outline:3px solid #2A1F4D;outline-offset:2px}.lr .num{font-variant-numeric:tabular-nums}.lr input::placeholder,.lr textarea::placeholder{color:#6E6690}";
const CAT: Record<string, { bg: string; fg: string; I: React.ComponentType<{ size?: number; color?: string }> }> = {
  Art: { bg: "#FFE3D9", fg: "#A8381A", I: Palette }, Code: { bg: "#ECE6FF", fg: "#5B3DBF", I: Terminal }, Cooking: { bg: "#FFEDC2", fg: "#8A5300", I: Utensils }, Photo: { bg: "#DCEEFF", fg: "#1F5E9C", I: Camera },
  Languages: { bg: "#D6F3EA", fg: "#0A6E55", I: Globe }, Finance: { bg: "#E4F3D3", fg: "#3F6A12", I: Wallet }, Design: { bg: "#FCE1EF", fg: "#A02D69", I: Pencil }, Lifestyle: { bg: "#DDF2E2", fg: "#22703F", I: Heart },
};
const cat = (k: unknown) => CAT[String(k)] || { bg: C.sunTint, fg: C.sunText, I: Book };
const CATS = ["Art", "Code", "Cooking", "Photo", "Languages", "Finance", "Design", "Lifestyle"];

function Cover({ c, className }: { c: R; className?: string }) {
  const [bad, setBad] = useState(false);
  const k = cat(c.category);
  const src = String(c.cover || "");
  if (bad || !src) return <div className={(className || "") + " grid place-items-center"} style={{ background: k.bg }}><k.I size={24} color={k.fg} /></div>;
  return <img src={src} alt="" className={className} onError={() => setBad(true)} />;
}
function Av({ name, cls }: { name: string; cls: string }) {
  const hues = ["#FFE3D9", "#ECE6FF", "#D6F3EA", "#DCEEFF", "#FFEDC2"];
  const fgs = ["#A8381A", "#5B3DBF", "#0A6E55", "#1F5E9C", "#8A5300"];
  const i = name.length % 5;
  return <span className={cls + " grid shrink-0 place-items-center rounded-full font-extrabold"} style={{ background: hues[i], color: fgs[i] }}>{name.split(" ").map((w) => w[0] || "").slice(0, 2).join("").toUpperCase()}</span>;
}
function ago(iso: unknown, now: number) {
  const t = new Date(String(iso || "")).getTime();
  if (!t) return "";
  if (!now) return new Date(t).toLocaleDateString("en-GB", { day: "numeric", month: "short" });
  const m = Math.max(0, Math.round((now - t) / 60000));
  if (m < 60) return m <= 1 ? "just now" : m + " min ago";
  const h = Math.round(m / 60);
  if (h < 24) return h + (h === 1 ? " hour ago" : " hours ago");
  const d = Math.round(h / 24);
  if (d === 1) return "yesterday";
  if (d < 7) return d + " days ago";
  return new Date(t).toLocaleDateString("en-GB", { day: "numeric", month: "short" });
}

