}

export type InstructorHomeProps = { app?: AppHandle };

export default function InstructorHome({ app }: InstructorHomeProps) {
  const reduce = useReducedMotion();
  const [open, setOpen] = useState(false);
  const [title, setTitle] = useState("");
  const [summary, setSummary] = useState("");
  const [category, setCategory] = useState("Art");
  const [level, setLevel] = useState("beginner");
  const [cover, setCover] = useState("");
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState<string | null>(null);
  const [now, setNow] = useState(0);
  useEffect(() => { setNow(new Date().getTime()); }, []);
  useEffect(() => {
    if (!open) return;
    const onKey = (e: KeyboardEvent) => { if (e.key === "Escape") setOpen(false); };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [open]);

  const courses = (app ? app.rows("course") : []) as R[];
  const meId = app ? app.me("instructor") : undefined;
  const me = ((app ? app.rows("instructor") : []) as R[]).find((i) => i.id === meId);
  const enrolls = (app ? app.rows("enrollment") : []) as R[];
  const attempts = (app ? app.rows("quiz_attempt") : []) as R[];
  const progress = (app ? app.rows("lesson_progress") : []) as R[];
  const students = (app ? app.rows("student") : []) as R[];
  const lessons = (app ? app.rows("lesson") : []) as R[];
  if (!app) return null;
  const hasProfile = !!meId;
  const mine = hasProfile ? courses.filter((c) => c.instructor_id === meId) : courses;
  const loading = app.loading("course") && courses.length === 0;
  const covers = Array.from(new Set(courses.map((c) => String(c.cover || "")).filter((s) => s.startsWith("http") || s.startsWith("/")))).slice(0, 8);
  const passRate = attempts.length ? Math.round((attempts.filter((a) => a.result === "passed").length / attempts.length) * 100) : 0;
  const activeStudents = new Set(enrolls.filter((e) => e.status !== "completed").map((e) => e.student_id)).size;
  const completions = enrolls.filter((e) => e.status === "completed").length;
  const weekAgo = now - 7 * 86400000;
  const lessonsThisWeek = now ? progress.filter((p) => new Date(String(p.created_at)).getTime() >= weekAgo).length : progress.length;
  const sName = (id: unknown) => { const s = students.find((x) => x.id === id); return s ? String(s.name) : "A student"; };
  const lTitle = (id: unknown) => { const l = lessons.find((x) => x.id === id); return l ? String(l.title) : "a lesson"; };
  const byTime = (a: R, b: R) => new Date(String(b.created_at)).getTime() - new Date(String(a.created_at)).getTime();

  const struggling: { key: string; student: unknown; lesson: unknown; tries: number; best: number; total: number; at: unknown }[] = [];
  [...attempts].sort(byTime).forEach((a) => {
    const key = String(a.student_id) + ":" + String(a.lesson_id);
    if (struggling.some((s) => s.key === key)) return;
    const all = attempts.filter((x) => x.student_id === a.student_id && x.lesson_id === a.lesson_id);
    if (all.some((x) => x.result === "passed")) return;
    struggling.push({ key, student: a.student_id, lesson: a.lesson_id, tries: all.length, best: all.reduce((m, x) => Math.max(m, Number(x.score) || 0), 0), total: Number(a.total) || 1, at: a.created_at });
  });

  const feed = [
    ...progress.map((p) => ({ id: "p" + p.id, at: p.created_at, who: sName(p.student_id), what: "finished " + lTitle(p.lesson_id), I: Check, tone: C.ok, tint: C.okTint })),
    ...enrolls.filter((e) => e.status === "completed").map((e) => ({ id: "c" + e.id, at: e.updated_at, who: sName(e.student_id), what: "completed " + String((courses.find((c) => c.id === e.course_id) || {}).title || "a course"), I: Trophy, tone: C.sunText, tint: C.sunTint })),
    ...enrolls.filter((e) => e.status === "enrolled").map((e) => ({ id: "e" + e.id, at: e.created_at, who: sName(e.student_id), what: "joined " + String((courses.find((c) => c.id === e.course_id) || {}).title || "a course"), I: Users, tone: "#1F5E9C", tint: "#DCEEFF" })),
  ].sort((a, b) => new Date(String(b.at)).getTime() - new Date(String(a.at)).getTime()).slice(0, 6);

  const create = async () => {
    if (!title.trim() || !summary.trim()) { setErr("Give your course a title and a one-line summary."); return; }
    setBusy(true); setErr(null);
    try {
      const row = await app.create("course", { title: title.trim(), summary: summary.trim(), category, level, cover: cover || covers[0] || "", instructor_id: meId });
