            <motion.p {...rise(1)} className="mt-1 text-lg font-semibold" style={{ color: C.mute }}>{hasProfile ? (mine.length ? "Here's how your " + mine.length + (mine.length === 1 ? " course is" : " courses are") + " doing." : "Your studio is ready for its first course.") : "Every course on Learnly, at a glance."}</motion.p>
          </div>
          {hasProfile && <motion.button {...rise(2)} onClick={() => { setErr(null); setOpen(true); }} className="flex h-12 items-center gap-2 rounded-full px-5 text-base font-extrabold transition-transform active:translate-y-[3px]" style={{ background: C.sun, boxShadow: "0 4px 0 " + C.sunDeep }}><Plus size={18} strokeWidth={3} />New course</motion.button>}
        </div>

        {!hasProfile && (
          <div className="mt-5 flex items-start gap-3 rounded-2xl p-4" style={{ background: "#DCEEFF" }}>
            <Info size={20} color="#1F5E9C" className="mt-0.5 shrink-0" />
            <p className="text-base font-semibold" style={{ color: "#173F68" }}>You're an admin without a teaching profile. Browse every course here; student progress is shown to each course's teacher. Manage people in <button onClick={() => app.navigate("/team")} className="font-extrabold underline underline-offset-2">Team &amp; access</button>.</p>
          </div>
        )}

        {hasProfile && (
          <motion.section {...rise(3)} aria-label="Summary" className="mt-6 grid grid-cols-2 gap-px overflow-hidden rounded-3xl lg:grid-cols-4" style={{ background: C.line, boxShadow: SHADOW }}>
            {stats.map((s) => (
              <div key={s.l} className="bg-white p-5"><p className="num text-3xl font-extrabold leading-none" style={{ fontFamily: DISPLAY }}>{s.v}</p><p className="mt-1.5 text-sm font-bold leading-snug" style={{ color: C.mute }}>{s.l}</p></div>
            ))}
          </motion.section>
        )}

        <div className="mt-8 grid grid-cols-1 gap-8 lg:grid-cols-[minmax(0,1fr)_340px]">
          <section aria-label="Courses" className="min-w-0">
            <h2 className="text-2xl font-extrabold tracking-tight" style={{ fontFamily: DISPLAY }}>{hasProfile ? "Your courses" : "All courses"}</h2>
            {loading ? (
              <div className="mt-3 flex flex-col gap-3" aria-busy="true" aria-label="Loading courses">{[0, 1, 2].map((i) => <div key={i} className="h-24 animate-pulse rounded-3xl" style={{ background: C.track }} />)}</div>
            ) : mine.length === 0 ? (
              <div className="mt-3 rounded-3xl bg-white px-6 py-12 text-center" style={{ boxShadow: SHADOW }}>
                <span className="mx-auto grid h-14 w-14 place-items-center rounded-2xl" style={{ background: C.sunTint }}><Book size={26} color={C.sunText} /></span>
                <p className="mt-4 text-2xl font-extrabold" style={{ fontFamily: DISPLAY }}>Create your first course</p>
                <p className="mx-auto mt-1 max-w-sm font-semibold" style={{ color: C.mute }}>Start with a title and a one-line promise. You'll add lessons and quiz questions next.</p>
                {hasProfile && <button onClick={() => setOpen(true)} className="mt-6 inline-flex h-12 items-center gap-2 rounded-full px-6 text-base font-extrabold" style={{ background: C.sun, boxShadow: "0 4px 0 " + C.sunDeep }}><Plus size={18} strokeWidth={3} />New course</button>}
