                  const avg = at.length ? Math.round((at.reduce((s, a) => s + Number(a.score) / Math.max(1, Number(a.total)), 0) / at.length) * 100) : null;
                  const rate = es.length ? Math.round((fin / es.length) * 100) : 0;
                  const k = cat(c.category);
                  return (
                    <motion.li key={c.id} {...rise(i + 4)}>
                      <button onClick={() => app.navigate("/teach/" + c.id)} className="flex w-full items-center gap-4 rounded-3xl bg-white p-3 text-left transition-shadow hover:shadow-lg sm:p-4" style={{ boxShadow: SHADOW }}>
                        <Cover c={c} className="h-20 w-20 shrink-0 rounded-2xl object-cover sm:h-24 sm:w-32" />
