            <motion.div role="dialog" aria-modal="true" aria-labelledby="lr-new-course" initial={{ y: reduce ? 0 : 40, opacity: 0 }} animate={{ y: 0, opacity: 1 }} exit={{ y: reduce ? 0 : 40, opacity: 0 }} transition={{ duration: reduce ? 0 : 0.3, ease: EASE }} onClick={(e) => e.stopPropagation()} className="max-h-[92dvh] w-full max-w-lg overflow-y-auto rounded-t-[28px] bg-white p-6 md:rounded-[28px]">
              <div className="flex items-center"><h2 id="lr-new-course" className="flex-1 text-2xl font-extrabold" style={{ fontFamily: DISPLAY }}>New course</h2><button aria-label="Close" onClick={() => setOpen(false)} className="grid h-11 w-11 place-items-center rounded-full" style={{ background: "rgba(42,31,77,.06)" }}><X size={20} /></button></div>
              <form onSubmit={(e) => { e.preventDefault(); create(); }} className="mt-4 flex flex-col gap-4">
                <label className="block"><span className="mb-1.5 block text-sm font-bold">Course title</span><input value={title} onChange={(e) => setTitle(e.target.value)} placeholder="e.g. Bread Without Fear" className={input} style={{ borderColor: C.line }} /></label>
                <label className="block"><span className="mb-1.5 block text-sm font-bold">One-line summary</span><textarea rows={2} value={summary} onChange={(e) => setSummary(e.target.value)} placeholder="What will students be able to do by the end?" className={input} style={{ borderColor: C.line }} /></label>
                <fieldset><legend className="mb-1.5 text-sm font-bold">Category</legend><div className="flex flex-wrap gap-2">{CATS.map((k) => <button type="button" key={k} aria-pressed={category === k} onClick={() => setCategory(k)} className="h-10 rounded-full border-2 px-3.5 text-sm font-extrabold" style={{ background: category === k ? C.ink : "#fff", color: category === k ? "#fff" : C.body, borderColor: category === k ? C.ink : C.line }}>{k}</button>)}</div></fieldset>
                <fieldset><legend className="mb-1.5 text-sm font-bold">Level</legend><div className="grid grid-cols-3 gap-1 rounded-full p-1" style={{ background: "#F1EEF6" }}>{["beginner", "intermediate", "advanced"].map((k) => <button type="button" key={k} aria-pressed={level === k} onClick={() => setLevel(k)} className="h-10 rounded-full text-sm font-extrabold capitalize" style={{ background: level === k ? "#fff" : "transparent", color: level === k ? C.ink : "#4F4670", boxShadow: level === k ? "0 1px 4px rgba(42,31,77,.14)" : "none" }}>{k}</button>)}</div></fieldset>
